def _numtxt(v):
    return str(int(v)) if float(v) == int(v) else repr(float(v))


NUM_TEXT = {}
for _aid in NUM_ABILS:
    _rs = [r_ for r_ in NUM_ROWS if r_[0].split(".")[1] == _aid]
    NUM_TEXT[_aid] = ",".join("%s=%s" % (r_[0].split(".")[2], _numtxt(r_[3])) for r_ in _rs)
    assert len(NUM_TEXT[_aid]) <= 380 and all(32 <= ord(c_) < 127 for c_ in NUM_TEXT[_aid]), _aid
    _pre = _rs[0][1].split("_")[0]
    _nm = dict((a[0], a[1]) for a in ABILS).get(_aid) or {'Momentum': 'Momentum', 'Elements': 'Element statuses'}[_aid]   # 0.1.25: + Momentum / Element statuses
    _r("ab.%s.numbers" % _aid, "%s_NUMS" % _pre, "text", NUM_TEXT[_aid], "", "400", "", _rs[0][7], (_nm + " numbers")[:40],
       ("key=value: time s, radius/range blocks, speed/slow/weaken %, power x one hit; no key = its default" if _aid not in NEW2_IDS + NEW3_IDS + ["Momentum", "Elements"] else
        ("key=value: stacks, s, blocks, %, power x one hit; no key = its default" if _aid in ("Momentum", "Elements") else
         "key=value: mana stamina cooldown = walking cost; s, blocks, %, power x one hit; no key = default")))
