# 0.1.26 (the ability tree redesign): the ability nodes (tier 0-4 = A1, A2, A3, A4a, A4b) + one modifier node per modifier ("A1.Power")
LINE_ID = {0: "A1", 1: "A2", 2: "A3", 3: "A4a", 4: "A4b"}
def tree_nodes(c):
    out = []
    for _a in sorted([a for a in ABILS if a[2] == c], key=lambda a: a[3]):
        out.append(LINE_ID[_a[3]])   # 0.1.30: no modifier nodes (modifiers unlock by ability level; SkyyTrees 0.3.18)
    return out
TREE_READS = ",".join("Class.%s.%s" % (_c, _n) for _c in ("Mage", "Priest", "Monk", "Assassin", "Warrior", "Berserker", "Archer", "Spellblade") for _n in tree_nodes(_c) + TREE_K[_c])
assert "Class.Priest.PA2" in TREE_READS and "Class.Priest.PB2" in TREE_READS and "Class.Mage.PC2" in TREE_READS and "Class.Mage.PA4" in TREE_READS   # 0.1.35; 0.1.38: PA4
assert "Class.Mage.A1" in TREE_READS and "Class.Mage.A4b" in TREE_READS and "Class.Assassin.A4b" not in TREE_READS and "M1A" not in TREE_READS
assert "Class.Mage.A1.Power" not in TREE_READS and ".Power" not in TREE_READS, "0.1.30: no modifier nodes"
