def cls_sub_java(prefix, cls_act):
    """0.1.34: the sub-tab row (HubBar.subTab into #<prefix>Sub): Class selected (action cls_act), the trees while Class is part of the
    Trees tab (SkyyTrees loaded: HubBar.selOf answers "trees"), actions clstr0 .. clstr8"""
    out = ['@PKG@.HubBar.subTab(b, ev, "%s", 0, "Class", true, "%s", %d);' % (prefix, cls_act, SUI.SUB_TAB_W),
           'if ("trees".equals(@PKG@.HubBar.selOf("character", "class"))) {']
    for j_, (lab_, _w) in enumerate(CLS_SUB_TREES):
        out.append('  @PKG@.HubBar.subTab(b, ev, "%s", %d, "%s", false, "clstr%d", %d);' % (prefix, j_ + 1, lab_, j_, SUI.SUB_TAB_W))
    out.append("}")
    return "\n".join(out)


def hub_page_checks(sh, what, content):
    """0.1.34: a Class page on the kit 1.7 hub_page - the shell + rows 1 + 2 (hub_page_preview, Trees selected) + the sub-tab row + the
    content's static pieces (content = [(parent, markup)]): check_page, assert_proven, the kit paths (tab art allowed), assert_menu_page
    (1600 x 980, rows 1 + 2, one sub row, no back / pager text, the content fits). Returns build()'s page17 statement (Trees selected while
    Class is merged: HubBar.selOf)."""
    pv = SUI.hub_page_preview(sh, tabs=[(r[0], SUI.hub_tab_label(HUB, r[0])) for r in SUI.hub_page_tabs(HUB)], my_tab=HUB_HOST)
    pv.extend(SUI.sub_tabs_preview(sh.prefix, CLS_SUB_LABELS, 0, SUI.SUB_TAB_W))
    for p_, mk_ in content:
        pv.append((p_, mk_))
    SUI.check_page(pv, sh.prefix[:-1])
    SUI.assert_proven(pv, what="0.1.34 " + what)
    SUI.check_sky_paths(pv, tab_icons=True)
    SUI.assert_menu_page(pv, sh, what=what)
    _hb = SUI.java_hub_page(sh, cls="@PKG@.HubBar", tab_expr='@PKG@.HubBar.selOf("character", "class")')
    assert _hb.count("page17(") == 1, what
    return _hb

