M(cfg, r"""
public static String kitMonk(java.util.Properties p, String d) {
  String v = p.getProperty("kit.Monk");
  if (v != null) return v.trim();
  String o = p.getProperty("kit.Shaman");
  if (o == null || o.trim().length() == 0) return d;
  info("kit.Monk: no kit.Monk line - using the old kit.Shaman line '" + o.trim() + "' as the Monk kit (file not changed; save the Monk kit in Server Setup to write kit.Monk)");
  return o.trim();
}""")
# 0.1.7: one plain item id (letters, digits, _ . -; no amount) - a bad hand-typed arrows.item falls back to the default
M(cfg, r"""
public static boolean itemIdOk(String id) {
  if (id == null || id.length() == 0 || id.length() > 120) return false;
  for (int i = 0; i < id.length(); i++) {
    char c = id.charAt(i);
    if (!((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_' || c == '.' || c == '-')) return false;
  }
  return true;
}""")
M(cfg, r"""
public static String fmtNum(double x) {
  if (x == Math.floor(x) && Math.abs(x) < 1.0E15) return String.valueOf((long) x);
  return String.valueOf((double) Math.round(x * 100.0) / 100.0);
}""")

