# heal one player: overheal is clamped first, then the per-second budget of that player is taken (0.1.11: with this hit's cap), then Health
# goes up
M(htask, r"""
public static double heal(@ST@ st, @REF@ r, java.util.UUID tu, double want, long now, double hitCap) {
  if (!(want > 0.01)) return 0.0;
  @ESM@ m = (@ESM@) st.getComponent(r, @ESM@.getComponentType());
  if (m == null) return 0.0;
  int hi = @DST@.getHealth();
  if (hi < 0) return 0.0;
  @ESV@ hv = m.get(hi);
  if (hv == null) return 0.0;
  double ask = room(want, hv.get(), hv.getMax());
  if (!(ask > 0.01)) return 0.0;
  double got = @PKG@.HealBudget.take(tu, ask, now, @PKG@.ClassCfg.HEAL_MAX_SEC, hitCap);
  if (!(got > 0.01)) return 0.0;
  m.addStatValue(hi, (float) got);
  return got;
}""")
