# one party member (never the Priest): online, same world (their Ref lives in this store = this thread), ready, alive, not creative, in range
M(htask, r"""
public double one(@ST@ st, @VEC@ c, String mid, double want, double r2, long now, String healer, double hitCap) {
  if (mid == null || mid.trim().length() == 0) return 0.0;
  java.util.UUID mu = java.util.UUID.fromString(mid.trim());
  if (mu.equals(this.u)) return 0.0;
  @PR@ mp = @UNI@.get().getPlayer(mu);
  if (mp == null || !mp.isValid()) return 0.0;
  @REF@ mr = mp.getReference();
  if (mr == null || !mr.isValid() || mr.getStore() != st) return 0.0;
  @PLA@ pl = (@PLA@) st.getComponent(mr, @PLA@.getComponentType());
  if (pl == null || pl.isWaitingForClientReady() || @PKG@.Kit.creative(pl) || !@PKG@.Kit.alive(st, mr)) return 0.0;
  @VEC@ mpos = pos(st, mr);
  if (mpos == null) return 0.0;
  double dx = mpos.x() - c.x();
  double dy = mpos.y() - c.y();
  double dz = mpos.z() - c.z();
  if (dx * dx + dy * dy + dz * dz > r2) return 0.0;
  double got = heal(st, mr, mu, want, now, hitCap);
  if (got > 0.0) {
    @PKG@.HealMsg.given(this.u, mu, got);
    @PKG@.HealMsg.taken(mu, this.u, healer, got);
  }
  return got;
}""")
# 0.1.12 (research/Magic-Traversal-Spec.md 3.2 + section 8): class:fn:heal / class:fn:ally helpers. A bridge argument as a UUID (a UUID or
# its String form; anything else = null). Pure.
M(htask, r"""
public static java.util.UUID uuidOf(Object o) {
  if (o == null) return null;
  if (o instanceof java.util.UUID) return (java.util.UUID) o;
  if (!(o instanceof String)) return null;
  try { return java.util.UUID.fromString(((String) o).trim()); } catch (Throwable t) { return null; }
}""")
# is b in a's party (party:fn:members of a)? SkyyParty missing / no answer / not in a party = false. Any thread.
M(htask, r"""
public static boolean inParty(java.util.UUID a, java.util.UUID b) {
  if (a == null || b == null) return false;
  String[] ms = members(a);
  if (ms == null) return false;
  String bs = b.toString();
  for (int i = 0; i < ms.length; i++) if (ms[i] != null && ms[i].trim().equalsIgnoreCase(bs)) return true;
  return false;
}""")
# class:fn:ally: the same player, or b in a's party (spec 8: traversal lock-ons target party members only). Later guilds.
M(htask, r"""
public static boolean ally(java.util.UUID a, java.util.UUID b) {
  if (a == null || b == null) return false;
  if (a.equals(b)) return true;
  return inParty(a, b);
}""")
# the heal one target gets (pure, bare-JVM tested): the healer + party members the full hp, every other player hp x othersPct % (0-100)
M(htask, r"""
public static double split(double hp, boolean party, long othersPct) {
  if (!(hp > 0.0) || Double.isInfinite(hp)) return 0.0;
  if (party) return hp;
  long q = othersPct < 0L ? 0L : (othersPct > 100L ? 100L : othersPct);
  return hp * (double) q / 100.0;
}""")
# the healer's wand CHARGED cap with the live config (0.1.11 capOf): max(maxPerHit, hpPerMana x its charged Mana); not a wand SkyyArmory
# knows / no item / no SkyyArmory = maxPerHit. Never throws.
M(htask, r"""
public static double chargedCap(String item) {
  double mana = wandMana(item);
  return capOf(mana, mana > 0.0, false, @PKG@.ClassCfg.HEAL_MAX_HIT, @PKG@.ClassCfg.HEAL_PER_MANA, @PKG@.ClassCfg.HEAL_QUICK_PCT);
}""")
F(htask, "public static volatile boolean OFF_THREAD_ONCE = false;")   # 0.1.12: an off-thread class:fn:heal call is logged once
# class:fn:heal (spec 3.2.1 + section 8): the target's world thread only (SkyyArmory's TravTick). Returns the HP really healed (0 = refused /
# nothing to heal). The order: switch -> arguments -> the healer is a Priest -> the target is an online player -> its world thread -> ready,
# alive, not creative -> split -> the wand's charged cap -> room -> the shared per-second budget -> addStatValue -> chat lines -> XP.
M(htask, r"""
public static double bridgeHeal(java.util.UUID healer, java.util.UUID target, double hp, String why, String wand) {
  if (!@PKG@.ClassCfg.HEAL_ON) return 0.0;
  if (healer == null || target == null || !(hp > 0.0) || Double.isInfinite(hp)) return 0.0;
  int ci = @PKG@.ClassStore.classIndex(healer);
  if (ci != @PKG@.ClassDefs.PRIEST || !@PKG@.ClassDefs.ENABLED[ci]) return 0.0;
  @PR@ tp = @UNI@.get().getPlayer(target);
  if (tp == null || !tp.isValid()) return 0.0;
  @REF@ tr = tp.getReference();
  if (tr == null || !tr.isValid()) return 0.0;
  @ST@ st = tr.getStore();
  if (st == null) return 0.0;
  Object ext = st.getExternalData();
  @WLD@ w = ext instanceof @ES@ ? ((@ES@) ext).getWorld() : null;
  if (w == null) return 0.0;
  if (!w.isInThread()) {
    if (!OFF_THREAD_ONCE) { OFF_THREAD_ONCE = true; @PKG@.ClassCfg.warn("class:fn:heal called off the target's world thread - refused (logged once; why=" + why + ")"); }
    return 0.0;
  }
  @PLA@ pl = (@PLA@) st.getComponent(tr, @PLA@.getComponentType());
  if (pl == null || pl.isWaitingForClientReady() || @PKG@.Kit.creative(pl) || !@PKG@.Kit.alive(st, tr)) return 0.0;
  boolean self = healer.equals(target);
  boolean party = self || inParty(healer, target);
  String item = wand != null && wand.length() > 0 ? wand : null;
  String name = null;
  boolean xpOk = false;
  @PR@ hpr = self ? tp : @UNI@.get().getPlayer(healer);
  if (hpr != null && hpr.isValid()) {
    name = hpr.getUsername();
    @REF@ hr = hpr.getReference();
    if (hr != null && hr.isValid() && hr.getStore() == st) {
      @PLA@ hpl = (@PLA@) st.getComponent(hr, @PLA@.getComponentType());
      xpOk = hpl != null && !@PKG@.Kit.creative(hpl) && @PKG@.Kit.alive(st, hr);
      if (item == null) {
        @IS@ main = @INVC@.getItemInHand(st, hr);
        if (main != null && !main.isEmpty()) item = main.getItemId();
      }
    }
  }
  double cap = chargedCap(item);
  double want = split(hp, party, @PKG@.ClassCfg.HEAL_OTHERS_PCT);
  if (want > cap) want = cap;
  double got = heal(st, tr, target, want, System.currentTimeMillis(), cap);
  if (!(got > 0.0)) return 0.0;
  @PKG@.HealMsg.given(healer, target, got);
  if (!self) @PKG@.HealMsg.taken(target, healer, name, got);
  if (xpOk) {
    if (self) xpSelf(healer, got);
    else xp(healer, got);
  }
  return got;
}""")
M(htask, r"""
public void run() {
  try {
    if (!@PKG@.ClassCfg.HEAL_ON) return;
    @PR@ pr = @UNI@.get().getPlayer(this.u);
    if (pr == null || !pr.isValid()) return;
    java.util.UUID wu = pr.getWorldUuid();
    @WLD@ w = wu == null ? null : @UNI@.get().getWorld(wu);
    if (w == null || this.world == null || !this.world.equals(w.getName())) return;
    @REF@ ref = pr.getReference();
    if (ref == null || !ref.isValid()) return;
    @ST@ st = ref.getStore();
    if (st == null) return;
    @PLA@ p = (@PLA@) st.getComponent(ref, @PLA@.getComponentType());
    if (p == null || p.isWaitingForClientReady() || @PKG@.Kit.creative(p) || !@PKG@.Kit.alive(st, ref)) return;
    @VEC@ c = pos(st, ref);
    if (c == null) return;
    double[] cc = caps(this.item, this.pid);   // 0.1.11: charged wand shot / quick shot / any other Priest hit
    double cap = cc[0];
    double top = cc[1];                        // fix round: a tap raises the 1 s window to its wand's CHARGED cap, the heal keeps the tap cap
    double want = want((double) this.dealt, @PKG@.ClassCfg.HEAL_SHARE_PCT, cap);
    if (!(want > 0.0)) return;
    double rad = @PKG@.ClassCfg.HEAL_RADIUS;
    double r2 = rad * rad;
    long now = System.currentTimeMillis();
    String[] ms = members(this.u);
    String healer = pr.getUsername();
    double others = 0.0;
    for (int i = 0; ms != null && i < ms.length; i++) {
      try { others = others + one(st, c, ms[i], want, r2, now, healer, top); } catch (Throwable t1) { failOnce(t1); }
    }
    double self = heal(st, ref, this.u, selfWant(want, @PKG@.ClassCfg.HEAL_SELF_PCT), now, top);
    if (self > 0.0) @PKG@.HealMsg.given(this.u, this.u, self);
    if (others > 0.0) xp(this.u, others);
    if (self > 0.0) xpSelf(this.u, self);   // 0.1.7
  } catch (Throwable t) { failOnce(t); }
}""")

# ================= 0.1.12 HealFn + AllyFn: class:fn:heal / class:fn:ally (research/Magic-Traversal-Spec.md 3.2, section 8) =================
# class:fn:heal apply(Object[]{UUID healer, UUID target, Double hp, String why [, String wandItemId]}) -> Double healed (0.0 = refused);
# UUIDs may also be their String form; the optional 5th element names the wand that cast (else the healer's main hand). Never throws.
hfn.addInterface(pool.get("java.util.function.Function"))
C(hfn, "public HealFn() { }")
M(hfn, r"""
public Object apply(Object o) {
  try {
    if (!(o instanceof Object[])) return Double.valueOf(0.0);
    Object[] a = (Object[]) o;
    if (a.length < 3 || !(a[2] instanceof Number)) return Double.valueOf(0.0);
    java.util.UUID h = @PKG@.HealTask.uuidOf(a[0]);
    java.util.UUID tg = @PKG@.HealTask.uuidOf(a[1]);
    double hp = ((Number) a[2]).doubleValue();
    String why = a.length > 3 && a[3] != null ? String.valueOf(a[3]) : null;
    String wand = a.length > 4 && a[4] instanceof String ? (String) a[4] : null;
    return Double.valueOf(@PKG@.HealTask.bridgeHeal(h, tg, hp, why, wand));
  } catch (Throwable t) { @PKG@.HealTask.failOnce(t); return Double.valueOf(0.0); }
}""")
# class:fn:ally apply(Object[]{UUID a, UUID b}) -> Boolean (same player or same party). Never throws (bad arguments = FALSE).
alfn.addInterface(pool.get("java.util.function.Function"))
C(alfn, "public AllyFn() { }")
M(alfn, r"""
public Object apply(Object o) {
  try {
    if (!(o instanceof Object[])) return Boolean.FALSE;
    Object[] a = (Object[]) o;
    if (a.length < 2) return Boolean.FALSE;
    return Boolean.valueOf(@PKG@.HealTask.ally(@PKG@.HealTask.uuidOf(a[0]), @PKG@.HealTask.uuidOf(a[1])));
  } catch (Throwable t) { return Boolean.FALSE; }
}""")

# ================= 0.1.6 PriestHealSys: DamageEventSystem in the INSPECT group (after ApplyDamage: only damage that really landed) =================
# Query.any (the target is an NPC; its component type is read inside like SkyySkills KillSys, so registration never depends on the NPC
# module's init order). No PvP: a target with a PlayerRef is skipped. No stat write inside the damage dispatch: HealTask runs next.
C(phs, "public PriestHealSys() { super(); }")
M(phs, r"""
public @QRY@ getQuery() {
  return @QRY@.any();
}""")
M(phs, r"""
public @SG@ getGroup() {
  return @DMOD@.get().getInspectDamageGroup();
}""")
# The creative check here is only an early out for melee (att = the attacker; for an orb att is not reliably the shooter, the reason
# DamageLock resolves orb shooters through Universe). The rule itself lives in HealTask.run: it resolves the Priest by UUID
# (Universe.getPlayer) and returns before any heal, chat line or XP when the Priest is in creative - for every hit, orbs included.
M(phs, r"""
public void handle(int idx, @ACH@ chunk, @ST@ st, @CB@ buf, @EV@ ev) {
  try {
    if (!@PKG@.ClassCfg.HEAL_ON) return;
    if (!(ev instanceof @DMG@)) return;
    @DMG@ d = (@DMG@) ev;
    if (d.isCancelled()) return;
    float dealt = d.getAmount();
    if (dealt < 1.0f) return;
    @DSRC@ src = d.getSource();
    if (!(src instanceof @DENT@)) return;
    @REF@ tg = chunk.getReferenceTo(idx);
    if (tg == null || !tg.isValid()) return;
    if (buf.getComponent(tg, @PR@.getComponentType()) != null) return;
    if (buf.getComponent(tg, @NPC@.getComponentType()) == null) return;
    @PKG@.ShotRec rec = null;
    if (src instanceof @DPRJ@) rec = @PKG@.ShotTrack.find(buf, ((@DPRJ@) src).getProjectile());
    @REF@ att = ((@DENT@) src).getRef();
    @PR@ apr = null;
    if (att != null && att.isValid()) apr = (@PR@) buf.getComponent(att, @PR@.getComponentType());
    java.util.UUID u = null;
    String item = null;
    String pid = null;   // 0.1.11: the projectile asset id of a shot (the heal cap: charged / quick / other)
    if (rec != null) {
      u = rec.shooter;
      item = rec.item;
      pid = rec.pid;
    } else {
      if (apr == null) return;
      u = apr.getUuid();
      @IS@ main = @INVC@.getItemInHand(buf, att);
      if (main != null && !main.isEmpty()) item = main.getItemId();
    }
    if (u == null || item == null) return;
    if (@PKG@.ClassDefs.ownerOf(item) != @PKG@.ClassDefs.PRIEST) return;
    int ci = @PKG@.ClassStore.classIndex(u);
    if (ci != @PKG@.ClassDefs.PRIEST || !@PKG@.ClassDefs.ENABLED[ci]) return;
    if (apr != null && u.equals(apr.getUuid())) {
      @PLA@ pl = (@PLA@) buf.getComponent(att, @PLA@.getComponentType());
      if (@PKG@.Kit.creative(pl)) return;
    }
    @WLD@ w = ((@ES@) buf.getExternalData()).getWorld();
    if (w == null) return;
    w.execute(new @PKG@.HealTask(u, dealt, w.getName(), item, pid));
  } catch (Throwable t) { @PKG@.ClassCfg.warnLimited("priest heal failed: " + t); }
}""")


