# last = last + (last - the one before)
M(abmods, r"""
public static long stepX(int k) {
  int[] st = steps();
  if (st.length == 0) return 0L;
  long last = (long) st[st.length - 1];
  long prev = st.length > 1 ? (long) st[st.length - 2] : 0L;
  long gap = last - prev;
  if (gap < 1L) gap = 1L;
  return last + gap * (long) k;
}""")
