M(abworld, r"""
public synchronized int addZone(@PKG@.AbilZone z) {
  if (z == null) return 0;
  int ended = 0;
  if (z.kind == 3 || z.kind == 4 || z.kind == 7 || z.kind == 8 || z.kind == 9 || z.kind == 12 || z.kind >= 13) { this.zones.add(z); this.nz = this.zones.size(); return 0; }   /* 0.1.24: the Warrior / Berserker / Archer zones keep their own limits (one banner, one frenzy / spin each; nets + rains end in seconds; Split makes 3 nets) */   // 0.1.18: short effects never count (0.1.22: + 7; 0.1.23: + the personal aura / stance / cloak)
  while (true) {
    int mine = 0;
    @PKG@.AbilZone oldest = null;
    for (int i = 0; i < this.zones.size(); i++) {
      @PKG@.AbilZone o = (@PKG@.AbilZone) this.zones.get(i);
      if (o.ended || o.caster == null || !o.caster.equals(z.caster)) continue;
      if (o.kind == 3 || o.kind == 4 || o.kind == 7 || o.kind == 8 || o.kind == 9 || o.kind == 12 || o.kind >= 13) continue;   // 0.1.18: Frost Wake / Running Blessing are not placed zones (0.1.22: + the star well; 0.1.23: + aura / stance / cloak)
      mine++;
      if (oldest == null || o.start < oldest.start) oldest = o;
    }
    if ((long) mine < @PKG@.AbilCfg.MAX_ZONES || oldest == null) break;
    oldest.ended = true;
    oldest.why = "replaced";
    ended++;
  }
  this.zones.add(z);
  this.nz = this.zones.size();
  return ended;
}""")
