# 0.1.39 (beta bug 6): no ability hit through blocks
F(abil, "public static volatile long LOS_MISS = 0L;")   # hits a wall stopped (/class debug + the harness)
ABIL_LATE += [
r"""
public static boolean losOpen(@CAC@ acc, double ax, double ay, double az, double bx, double by, double bz) {
  double dx = bx - ax;
  double dy = by - ay;
  double dz = bz - az;
  double l = Math.sqrt(dx * dx + dy * dy + dz * dz);
  if (!(l > 1.0E-6) || Double.isInfinite(l)) return true;
  int n = (int) Math.ceil(l / 0.25);
  if (n > 512) n = 512;
  int x0 = (int) Math.floor(ax);
  int y0 = (int) Math.floor(ay);
  int z0 = (int) Math.floor(az);
  int x1 = (int) Math.floor(bx);
  int y1 = (int) Math.floor(by);
  int z1 = (int) Math.floor(bz);
  for (int k = 1; k < n; k++) {   // every 0.25 block; the start block (the centre's own) and the end block (the enemy's) are skipped
    double u = (double) k / (double) n;
    int x = (int) Math.floor(ax + dx * u);
    int y = (int) Math.floor(ay + dy * u);
    int z = (int) Math.floor(az + dz * u);
    if ((x == x0 && y == y0 && z == z0) || (x == x1 && y == y1 && z == z1)) continue;
    if (arcSolid(acc, (double) x + 0.5, (double) y + 0.5, (double) z + 0.5) == 1) return false;   // only SOLID closes it (-1 unreadable / 0 open never)
  }
  return true;
}
""",
r"""
public static boolean losOk(@CAC@ acc, double ax, double ay, double az, @REF@ t) {
  if (!@PKG@.AbilCfg.LOS_ON || t == null) return true;
  @VEC@ q = pos(acc, t);
  if (q == null) return true;
  if (losOpen(acc, ax, ay, az, q.x, q.y + 0.9, q.z)) return true;   // its middle, its top, its lower body: any open line = seen
  if (losOpen(acc, ax, ay, az, q.x, q.y + 1.5, q.z)) return true;
  if (losOpen(acc, ax, ay, az, q.x, q.y + 0.4, q.z)) return true;
  LOS_MISS = LOS_MISS + 1L;
  return false;
}
""",
]
