M(abpage, r"""
public void handleDataEvent(@REF@ ref, @ST@ st, String data) {
  try {
    if (data == null) return;
    if (data.indexOf("absub") >= 0) {     // 0.1.34: the Class sub-tab = the old Class tab click (the class page / the class tree)
      if (!@PKG@.ClassHubOpen.openOn(this.playerRef, ref, st)) { this.pending = -1; this.pick = false; this.info = "The class page could not open right now - try /class."; rebuild(); }
      return;
    }
    String tw = null;
    if (data.indexOf("clstr0") >= 0) tw = "mining";
    else if (data.indexOf("clstr1") >= 0) tw = "foraging";
    else if (data.indexOf("clstr2") >= 0) tw = "farming";
    else if (data.indexOf("clstr3") >= 0) tw = "fishing";
    else if (data.indexOf("clstr4") >= 0) tw = "alchemy";
    else if (data.indexOf("clstr5") >= 0) tw = "smithing";
    else if (data.indexOf("clstr6") >= 0) tw = "cooking";
    else if (data.indexOf("clstr7") >= 0) tw = "acrobatics";
    else if (data.indexOf("clstr8") >= 0) tw = "exploration";
    if (tw != null) { if (@PKG@.HubBar.run(this.playerRef, "tree " + tw) != 0) { this.pending = -1; this.pick = false; this.info = "The skill trees could not open right now - try /tree."; rebuild(); } return; }   // 0.1.34: a tree sub-tab
    String hr = @PKG@.HubBar.route(this.playerRef, data, "character", "class");     // 0.1.34: route (+ row 1); 0.1.27 hubs: the bar first (null = not a hub click)
    if (hr != null) {
      if (hr.equals("close")) { close(); return; }
      if (hr.equals("self")) {     // the Class tab on the Abilities page = back to the class page (its main view)
        if (!@PKG@.ClassHubOpen.openOn(this.playerRef, ref, st)) { this.pending = -1; this.pick = false; this.info = "The class page could not open right now - try /class."; rebuild(); }
        return;
      }
      if (!hr.equals("bridge") && !hr.equals("command") && !hr.equals("back")) { this.pending = -1; this.pick = false; this.info = "That tab could not open right now - try again."; rebuild(); }
      return;
    }
    if (data.indexOf("abclose\"") >= 0) { close(); return; }
    java.util.UUID u = this.playerRef.getUuid();
    int ci = @PKG@.ClassStore.classIndex(u);
    if (ci < 0 || !@PKG@.AbilDefs.classHas(ci)) {
      this.pending = -1;
      this.pick = false;
      this.info = ci < 0 ? @PKG@.Abil.noClass() : "Your class has no abilities yet.";
      rebuild(); return;
    }
    if (@PKG@.Abil.combatMs(u) > 0L) {
      this.pending = -1;
      this.pick = false;
      this.info = "Leave combat first - abilities change only out of combat.";
      rebuild(); return;
    }
    String k = @PKG@.ClassCfg.pkey(u);
    for (int i = 0; i < 4; i++) {
      if (data.indexOf("abmove" + i + "\"") < 0) continue;
      this.pick = false;
      if (this.pending == i) { this.pending = -1; this.info = ""; rebuild(); return; }
      if (this.pending < 0) {
        String[] sl = @PKG@.AbilStore.slots(k, ci);
        int ai = @PKG@.AbilDefs.find(sl[i]);
        if (ai < 0 || !@PKG@.AbilDefs.owns(ai, @PKG@.Abil.level(u, ci), @PKG@.AbilStore.granted(k), @PKG@.AbilStore.pick(k))) {
          this.info = (ai < 0 ? "That slot" : @PKG@.AbilDefs.NAMES[ai]) + " is locked.";
          rebuild(); return;
        }
        this.pending = i;
        this.info = "Now press Swap here on the card to trade places with " + @PKG@.AbilDefs.NAMES[ai] + " (or Cancel).";
        rebuild(); return;
      }
      int p = this.pending;
      this.pending = -1;
      String r = @PKG@.Abil.swapSlots(u, p, i);
      this.info = r.startsWith("ok:") ? r.substring(3) : r;
      rebuild(); return;
    }
    if (data.indexOf("abpick\"") >= 0) {
      this.pending = -1;
      if (@PKG@.Abil.treeOwnsPick(u)) { this.info = "Your Ability 1 alt is the A4 node you buy in your class tree (/tree class) - a class respec lets you pick the other one."; rebuild(); return; }   // 0.1.26
      long need = @PKG@.AbilDefs.unlock(3);
      if (!@PKG@.AbilStore.granted(k) && (long) @PKG@.Abil.level(u, ci) < need) {
        this.info = "You choose your Ability 1 alt at " + @PKG@.ClassDefs.SKILLS[ci] + " " + need + ".";
        rebuild(); return;
      }
      this.pick = true;
      this.info = "";
      rebuild(); return;
    }
    if (data.indexOf("abyes\"") >= 0) {
      if (!this.pick) return;
      this.pick = false;
      if (@PKG@.Abil.treeOwnsPick(u)) { this.info = "Your Ability 1 alt is the A4 node you buy in your class tree (/tree class)."; rebuild(); return; }   // 0.1.26
      this.info = @PKG@.Abil.setPick(k, ci, @PKG@.AbilStore.pick(k).equals("B") ? "A" : "B");
      rebuild(); return;
    }
    if (data.indexOf("abno\"") >= 0) { this.pick = false; this.info = ""; rebuild(); return; }
  } catch (Throwable t) { @PKG@.ClassCfg.warn("abilities page event failed: " + t); }
}""")

# ================= OpenTask: first-join page open (SkyyHud AttachTask pattern: delay, world-thread hop, WorldMap channel gate) =================
# Only without SkyyProfiles. Cross-mod timeline pass (same guards as SkyyProfiles' Create Profile page): calm resets when the player's
# world changes between polls (opens only after 2 polls in one world); waits up to ISLAND_WAIT_MS while the player stands in a
# skyy-island-* world (SkyyIslands routes island logins to the hub 1.5 s after the first PlayerReadyEvent - a page opened just before
# that teleport is lost); never replaces an open custom page (our own ClassPage opened with /class -> done; any other, e.g. the
# SkyyMenu page -> wait until it is closed); never opens over the respawn screen. Gives up after 240 polls (2 min).
opn.addInterface(pool.get("java.lang.Runnable"))
F(opn, "public static final long ISLAND_WAIT_MS = 8000L;")
F(opn, "public @PR@ pr;")
F(opn, "public boolean onWorld;")
F(opn, "public int calm;")
F(opn, "public int tries;")
F(opn, "public java.util.UUID wu;")
F(opn, "public java.util.UUID lastWorld;")
F(opn, "public long born;")
C(opn, "public OpenTask(@PR@ pr) { this.pr = pr; this.onWorld = false; this.calm = 0; this.tries = 0; this.wu = null; this.lastWorld = null; this.born = System.currentTimeMillis(); }")
M(opn, r"""
public void later(long ms) {
  this.onWorld = false;
  @HSV@.SCHEDULED_EXECUTOR.schedule(this, ms, java.util.concurrent.TimeUnit.MILLISECONDS);
}""")
M(opn, r"""
public void again(boolean unsettled) {
  if (unsettled) this.calm = 0;
  if (++this.tries < 240) later(500L);
}""")
M(opn, r"""
public void run() {
  try {
    if (pr == null || !pr.isValid()) return;
    if (!this.onWorld) {
      java.util.UUID wu = pr.getWorldUuid();
      if (wu == null) { again(true); return; }
      @WLD@ w = @UNI@.get().getWorld(wu);
      if (w == null) { again(true); return; }
      this.wu = wu;
      this.onWorld = true;
      w.execute(this);
      return;
    }
    java.util.UUID now = pr.getWorldUuid();
    if (now == null || !now.equals(this.wu)) { again(true); return; }
    if (@PKG@.ClassCfg.profilesOn()) return;
    if (@PKG@.ClassStore.classIndex(pr.getUuid()) >= 0) return;
    if (this.lastWorld == null || !this.lastWorld.equals(now)) { this.lastWorld = now; this.calm = 0; }
    @WLD@ here = @UNI@.get().getWorld(now);
    String wn = here == null ? null : here.getName();
    if (wn != null && wn.startsWith("skyy-island-") && System.currentTimeMillis() - this.born < ISLAND_WAIT_MS) { again(true); return; }
    @REF@ r = pr.getReference();
    if (r == null) { again(true); return; }
    @ST@ st = r.getStore();
    if (st == null) { again(true); return; }
    @PLA@ player = (@PLA@) st.getComponent(r, @PLA@.getComponentType());
    if (player == null) { again(true); return; }
    if (st.getComponent(r, com.hypixel.hytale.server.core.modules.entity.damage.DeathComponent.getComponentType()) != null) { again(true); return; }
    Object cp = player.getPageManager().getCustomPage();
    if (cp instanceof @PKG@.ClassPage) return;
    if (cp != null) { again(true); return; }
    boolean writable = true;
    try {
      com.hypixel.hytale.server.core.io.PacketHandler ph = player.getPlayerConnection();
      com.hypixel.hytale.protocol.io.ChannelConnection ch = ph == null ? null : ph.getChannel(com.hypixel.hytale.protocol.NetworkChannel.WorldMap);
      writable = ch == null || ch.isWritable();
    } catch (Throwable t) { writable = true; }
    if (writable) this.calm++; else this.calm = 0;
    if (this.calm < 2) { again(false); return; }
    player.getPageManager().openCustomPage(r, st, new @PKG@.ClassPage(pr));
    @PKG@.ClassStore.markPrompted(pr.getUuid());
  } catch (Throwable t) { @PKG@.ClassCfg.warn("could not open the class page on join: " + t); }
}""")

