F(abload, "public static volatile long SETS = 0L;")
M(abload, r"""
public static String esc(String s) {
  if (s == null) return "";
  return s.replace(';', ' ').replace('=', ' ').replace('|', ' ').replace('\n', ' ').replace('\r', ' ').trim();
}""")
# the value of one key of a snapshot ("k=v;k=v"), null when the key is absent
M(abload, r"""
public static String val(String snap, String key) {
  if (snap == null || key == null) return null;
  String[] parts = snap.split(";");
  for (int i = 0; i < parts.length; i++) {
    int e = parts[i].indexOf('=');
    if (e <= 0) continue;
    if (parts[i].substring(0, e).trim().equals(key)) return parts[i].substring(e + 1).trim();
  }
  return null;
}""")
M(abload, r"""
public static String name(String id) {
  int a = @PKG@.AbilDefs.find(id);
  return a < 0 ? (id == null || id.length() == 0 ? "-" : id) : @PKG@.AbilDefs.NAMES[a];
}""")
M(abload, r"""
public static String get(java.util.UUID u) {
  if (u == null) return null;
  int ci = @PKG@.ClassStore.classIndex(u);
  if (ci < 0 || !@PKG@.AbilDefs.classHas(ci)) return null;
  GETS = GETS + 1L;
  String k = @PKG@.ClassCfg.pkey(u);
  String pk = @PKG@.AbilStore.pick(k);
  String[] sl = @PKG@.AbilStore.slots(k, ci);
  String[] keys = new String[] { "p1", "p2", "a1", "a2" };
  StringBuilder sb = new StringBuilder();
  sb.append("v=1;class=").append(esc(@PKG@.ClassDefs.NAMES[ci])).append(";alt=").append(pk);
  for (int i = 0; i < 4; i++) sb.append(';').append(keys[i]).append('=').append(esc(sl[i]));
  for (int i = 0; i < 4; i++) sb.append(";n").append(i + 1).append('=').append(esc(name(sl[i])));
  sb.append(";mods=");
  java.util.Properties p = @PKG@.AbilStore.load(k);
  String ms = "";
  for (int ai = 0; ai < @PKG@.AbilDefs.IDS.length; ai++) {
    if (@PKG@.AbilDefs.CLS[ai] != ci) continue;
    String[] e = @PKG@.Abil.eqOf(p, @PKG@.AbilDefs.IDS[ai]);
    if (e[0].length() == 0 && e[1].length() == 0) continue;
    ms = ms + (ms.length() > 0 ? "/" : "") + @PKG@.AbilDefs.IDS[ai] + ":" + (e[0].length() == 0 ? "-" : esc(e[0])) + "+" + (e[1].length() == 0 ? "-" : esc(e[1]));
  }
  sb.append(ms);
  return sb.toString();
}""")
M(abload, r"""
public static boolean same(String[] a, String[] b) {
  if (a == null || b == null || a.length != b.length) return false;
  for (int i = 0; i < a.length; i++) if (a[i] == null ? b[i] != null : !a[i].equals(b[i])) return false;
  return true;
}""")
M(abload, r"""
public static String apply(java.util.UUID u, String snap) {
  if (u == null || snap == null || !"1".equals(val(snap, "v"))) return "-Not an ability loadout - abilities not changed.";
  int ci = @PKG@.ClassStore.classIndex(u);
  if (ci < 0 || !@PKG@.AbilDefs.classHas(ci)) return "-Your class has no abilities - abilities not changed.";
  String sc = val(snap, "class");
  if (sc == null || !@PKG@.ClassDefs.NAMES[ci].equalsIgnoreCase(sc)) return "-These abilities are for a " + (sc == null ? "?" : sc) + " - you are a " + @PKG@.ClassDefs.NAMES[ci] + ". Abilities not changed.";
  SETS = SETS + 1L;
  String k = @PKG@.ClassCfg.pkey(u);
  int lv = @PKG@.Abil.level(u, ci);
  boolean grant = @PKG@.AbilStore.granted(k);
  String cur = @PKG@.AbilStore.pick(k);
  String want = "B".equalsIgnoreCase(val(snap, "alt")) ? "B" : "A";
  StringBuilder skip = new StringBuilder();
  String ep = cur;
  boolean pickCh = false;
  if (!want.equals(cur)) {
    int na = @PKG@.AbilDefs.of(ci, @PKG@.AbilDefs.pickTier(want));
    long altLv = @PKG@.AbilDefs.unlock(3);
    if (na < 0) skip.append("the Ability 1 alt pick (your class has none)");
    else if (grant || (long) lv >= altLv) { ep = want; pickCh = true; }
    else skip.append(@PKG@.AbilDefs.NAMES[na] + " (choose it at " + @PKG@.ClassDefs.SKILLS[ci] + " " + altLv + ")");
  }
  String[] curSl = @PKG@.AbilStore.slots(k, ci);
  String[] base = new String[] { curSl[0], curSl[1], curSl[2], curSl[3] };
  if (pickCh) {
    int oa = @PKG@.AbilDefs.of(ci, @PKG@.AbilDefs.pickTier(cur));
    int nb = @PKG@.AbilDefs.of(ci, @PKG@.AbilDefs.pickTier(ep));
    for (int i = 0; i < 4; i++) if (oa >= 0 && nb >= 0 && @PKG@.AbilDefs.IDS[oa].equals(base[i])) base[i] = @PKG@.AbilDefs.IDS[nb];
  }
  String[] ds = new String[] { val(snap, "p1"), val(snap, "p2"), val(snap, "a1"), val(snap, "a2") };
  String[] v = @PKG@.AbilDefs.valid(ds, ci, ep);
  String[] fin = base;
  if (v == null) {
    if (skip.length() > 0) skip.append(", ");
    skip.append("the slot order (it does not match your abilities now)");
  } else {
    String locked = null;
    for (int i = 0; i < 4 && locked == null; i++) {
      if (v[i].equals(base[i])) continue;
      int a = @PKG@.AbilDefs.find(v[i]);
      int b = @PKG@.AbilDefs.find(base[i]);
      if (a < 0 || !@PKG@.AbilDefs.owns(a, lv, grant, ep)) locked = a < 0 ? v[i] : @PKG@.AbilDefs.NAMES[a];
      else if (b < 0 || !@PKG@.AbilDefs.owns(b, lv, grant, ep)) locked = b < 0 ? base[i] : @PKG@.AbilDefs.NAMES[b];
    }
    if (locked == null) fin = v;
    else {
      if (skip.length() > 0) skip.append(", ");
      skip.append("the slot order (" + locked + " is still locked)");
    }
  }
  String mods = val(snap, "mods");
  String mdone = "";
  if (mods != null && mods.length() > 0) {   // 0.1.22: "Meteor:Power+Echo/ManaBarrier:Ward+-" - each one through the panel's own rules
    String csv = @PKG@.Abil.treeCsv(u);
    String[] ab = mods.split("/");
    for (int i = 0; i < ab.length; i++) {
      int c = ab[i].indexOf(':');
      if (c <= 0) continue;
      String aid = ab[i].substring(0, c).trim();
      String[] two = ab[i].substring(c + 1).split("\\+");
      for (int sl = 0; sl < 2; sl++) {
        String md = sl < two.length ? two[sl].trim() : "-";
        if (md.equals("-")) md = "";
        String r = @PKG@.Abil.equipMod(u, aid, sl, md, csv, true);
        if (r.startsWith("+")) mdone = aid;
        else if (!(md.length() == 0 && r.indexOf("is empty") >= 0) && r.indexOf("is already in slot") < 0) {
          if (skip.length() > 0) skip.append(", ");
          skip.append(aid + " slot " + (sl + 1) + " (" + r.substring(1) + ")");
        }
      }
    }
  }
  if (pickCh || !same(fin, curSl)) {
    if (!@PKG@.AbilStore.set(k, new String[] { "alt", "p1", "p2", "a1", "a2" }, new String[] { ep, fin[0], fin[1], fin[2], fin[3] }))
      return "-Your ability file could not be read - abilities not changed (see the server log).";
    @PKG@.AbilStore.saveSoon(k);
  }
  String done = "Abilities: /cast 1 " + name(fin[0]) + ", /cast 2 " + name(fin[1]) + ", alts " + name(fin[2]) + " and " + name(fin[3]) + ".";
  if (skip.length() == 0) return "+" + done;
  return "=" + done + " Skipped: " + skip.toString() + ".";
}""")
